DROP TABLE IF EXISTS "ai_conversations";
DROP SEQUENCE IF EXISTS "public".ai_conversations_id_seq;
CREATE SEQUENCE "public".ai_conversations_id_seq INCREMENT 1 MINVALUE 1 MAXVALUE 2147483647 CACHE 1;

CREATE TABLE "public"."ai_conversations" (
    "id" integer DEFAULT nextval('ai_conversations_id_seq') NOT NULL,
    "telegram_id" bigint NOT NULL,
    "username" text,
    "full_name" text,
    "created_at" timestamp DEFAULT now(),
    "updated_at" timestamp DEFAULT now(),
    "phone" text NOT NULL,
    CONSTRAINT "ai_conversations_pkey" PRIMARY KEY ("id")
)
WITH (oids = false);

CREATE UNIQUE INDEX uq_ai_conversations_telegram_id ON public.ai_conversations USING btree (telegram_id);

