DROP TABLE IF EXISTS "ai_messages";
DROP SEQUENCE IF EXISTS "public".ai_messages_id_seq;
CREATE SEQUENCE "public".ai_messages_id_seq INCREMENT 1 MINVALUE 1 MAXVALUE 2147483647 CACHE 1;

CREATE TABLE "public"."ai_messages" (
    "id" integer DEFAULT nextval('ai_messages_id_seq') NOT NULL,
    "conversation_id" integer NOT NULL,
    "role" character varying(20) NOT NULL,
    "message" text NOT NULL,
    "created_at" timestamp DEFAULT now(),
    CONSTRAINT "ai_messages_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "ai_messages_role_check" CHECK ((((role)::text = ANY ((ARRAY['user'::character varying, 'assistant'::character varying])::text[]))))
)
