DROP TABLE IF EXISTS "chats";
DROP SEQUENCE IF EXISTS "public".chats_id_seq;
CREATE SEQUENCE "public".chats_id_seq INCREMENT 1 MINVALUE 1 MAXVALUE 2147483647 CACHE 1;

CREATE TABLE "public"."chats" (
    "id" integer DEFAULT nextval('chats_id_seq') NOT NULL,
    "student_id" bigint NOT NULL,
    "student_name" character varying(255),
    "phone" character varying(50),
    "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
    "consultant_mode" boolean DEFAULT true,
    CONSTRAINT "chats_pkey" PRIMARY KEY ("id")
)
WITH (oids = false);

CREATE UNIQUE INDEX chats_student_id_key ON public.chats USING btree (student_id);

