CREATE SEQUENCE "public".chunks_id_seq1 INCREMENT 1 MINVALUE 1 MAXVALUE 2147483647 CACHE 1;

CREATE TABLE "public"."chunks" (
    "id" integer DEFAULT nextval('chunks_id_seq1') NOT NULL,
