INSERT INTO "chunks" ("id", "document_id", "text", "embedding") VALUES
(277,	18,	'Статья 180. Сепаратистская деятельность
1. Пропаганда или публичные призывы к нарушению унитарности и целостности
Республики Казахстан, неприкосновенности и неотчуждаемости ее территории либо
дезинтеграции государства, а равно изготовление, хранение с целью распространения или
распространение материалов такого содержания –
наказываются штрафом в размере от одной тысячи до пяти тысяч месячных расчетных
показателей либо ограничением свободы на срок до семи лет, либо лишением свободы на
тот же срок.
2. Те же действия, совершенные лицом с использованием своего служебного
положения либо лидером общественного объединения, либо с использованием масс-медиа,
сетей телекоммуникаций или онлайн-платформ, либо группой лиц или группой лиц по
предварительному сговору, в том числе с использованием средств, полученных из
иностранных источников, –
наказываются лишением свободы на срок от пяти до десяти лет.
3. Действия, совершенные с целью нарушения унитарности и целостности Республики
